    for name, qty in stock.items():
        if qty < limit:
            names.append(name)
    return sorted(names)

print(low_stock(stock))

def sell(stock, item, qty):
    if item not in stock:
        return False
    if qty <= 0 or qty > stock[item]:
        return False
    stock[item] -= qty
    return True

print(sell(stock, "simit", 1))

