import math

def crates_needed(qty, per_crate=6):
    return math.ceil(qty / per_crate)

def order_plan(stock, limit=10, target=24, per_crate=6):
    plan = {}
    for name in low_stock(stock, limit):
        missing = target - stock[name]
        plan[name] = crates_needed(missing, per_crate)
    return plan

print(order_plan(stock))
